trt_summary <- bind_rows(lapply(names(vp_pars), function(nm) {   o0 <- run_ogtt(vp_pars[[nm]], fasting[[nm]], treated = 0)   o1 <- run_ogtt(vp_pars[[nm]], fasting[[nm]], treated = 1)   tibble::tibble(     VP = nm,     `Peak conversion rate (pM/min)` = max(o0$proinsulinPlasma) / 20,     `Peak insulin untreated (pM)`   = max(o0$insulinPlasma),     `Peak insulin treated (pM)`     = max(o1$insulinPlasma),     `Insulin rise (pM)`             = max(o1$insulinPlasma) - max(o0$insulinPlasma),     `Mean glucose change (mg/dL)`   = mean(o1$glucosePlasma) - mean(o0$glucosePlasma)   ) })) knitr::kable(trt_summary, digits = 2) stopifnot(   # "conversion rates of up to ~7 pM/min were explored" -- the tabulated   # K_CPro = 20 min produces peak rates that bracket 7 pM/min across the VPs.   min(trt_summary$`Peak conversion rate (pM/min)`) < 7,   max(trt_summary$`Peak conversion rate (pM/min)`) > 7,   # "insulin levels increase by ~10 pM at the peak of secretion"   all(trt_summary$`Insulin rise (pM)` > 2),   all(trt_summary$`Insulin rise (pM)` < 20),   # the paper's central negative finding: glucose barely moves   all(abs(trt_summary$`Mean glucose change (mg/dL)`) < 5) ) cat(sprintf("Peak conversion rates span %.1f-%.1f pM/min, bracketing the ~7 pM/min of Section 2.6;
",             min(trt_summary$`Peak conversion rate (pM/min)`),             max(trt_summary$`Peak conversion rate (pM/min)`))) #> Peak conversion rates span 1.9-10.7 pM/min, bracketing the ~7 pM/min of Section 2.6; cat(sprintf("insulin rises %.1f-%.1f pM at the OGTT peak against the ~10 pM of Section 3.2;
",             min(trt_summary$`Insulin rise (pM)`), max(trt_summary$`Insulin rise (pM)`))) #> insulin rises 2.8-13.7 pM at the OGTT peak against the ~10 pM of Section 3.2; cat(sprintf("mean OGTT glucose falls by only %.2f-%.2f mg/dL across the VPs.
",             min(abs(trt_summary$`Mean glucose change (mg/dL)`)),             max(abs(trt_summary$`Mean glucose change (mg/dL)`)))) #> mean OGTT glucose falls by only 0.78-2.61 mg/dL across the VPs.

